(function(){
'use strict';
const KEY='nawaf-hq-v5';
let last='';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'ceo-decision'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function addActivity(s,text,type='REAL'){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:uid('a'),text,type,at:new Date().toISOString()});s.activity=s.activity.slice(0,120)}
function employee(s,id){return (s.employees||[]).find(e=>e.id===id)}
function projectName(s,id){return (s.projects||[]).find(p=>p.id===id)?.name||'بدون مشروع'}
function resultText(t){const r=t?.aiResult||{};return String(r.summary||r.deliverable||r.result||r.text||'').trim()}
function toast(text){const x=document.querySelector('.toast');if(!x)return;x.textContent=text;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),2800)}
function normalize(){const s=read();s.tasks=Array.isArray(s.tasks)?s.tasks:[];s.approvals=Array.isArray(s.approvals)?s.approvals:[];let changed=false;for(const t of s.tasks){if(t.status==='WAITING_FOR_NAWAF'){
 let a=s.approvals.find(x=>x.taskId===t.id&&x.status==='WAITING');
 if(!a){const e=employee(s,t.employeeId);a={id:uid('ap'),taskId:t.id,employeeId:t.employeeId||'',projectId:t.projectId||'',title:t.title||'قرار مطلوب',summary:resultText(t).slice(0,700),requester:e?.name||'موظف AI',status:'WAITING',createdAt:new Date().toISOString()};s.approvals.unshift(a);addActivity(s,(e?.name||'موظف AI')+' رفع قرارًا لنواف: '+a.title,'APPROVAL');changed=true}
 window.NawafHQ3D?.routeEmployee?.(t.employeeId,'WAITING_FOR_NAWAF');
 }}
 for(const a of s.approvals){if(a.status!=='WAITING')continue;const t=s.tasks.find(x=>x.id===a.taskId);if(!t||t.status!=='WAITING_FOR_NAWAF'){a.status='RESOLVED';a.resolvedAt=new Date().toISOString();changed=true}}
 if(changed)write(s,'approval-normalized');return s}
async function cloudPush(){try{if(window.HQCloudReady)await window.HQCloudReady;if(window.HQCloud?.push)await window.HQCloud.push()}catch{}}
function decide(id,action){const s=read(),a=(s.approvals||[]).find(x=>x.id===id);if(!a||a.status!=='WAITING')return;const t=(s.tasks||[]).find(x=>x.id===a.taskId),e=t?employee(s,t.employeeId):null;if(!t)return;
 const now=new Date().toISOString();let rerun=false;
 if(action==='approve'){
  a.status='APPROVED';a.resolvedAt=now;t.status='READY';t.progress=Math.min(Number(t.progress)||0,95);t.ceoDecision={decision:'APPROVED',at:now};if(e){e.status='READY';e.task=t.title}addActivity(s,'نواف اعتمد: '+t.title,'REAL');rerun=true;toast('تم الاعتماد وسيكمل الموظف التنفيذ.');
 }else if(action==='changes'){
  const note=window.prompt('اكتب التعديل المطلوب من الموظف:','');if(note===null)return;a.status='CHANGES_REQUESTED';a.resolvedAt=now;a.note=note;t.details=(t.details||t.title||'')+'\n\nتوجيه نواف: '+note;t.status='READY';t.progress=0;t.ceoDecision={decision:'CHANGES_REQUESTED',note,at:now};if(e){e.status='READY';e.task=t.title}addActivity(s,'نواف طلب تعديلات على: '+t.title,'REAL');rerun=true;toast('تم إرسال التعديلات للموظف.');
 }else if(action==='reject'){
  a.status='REJECTED';a.resolvedAt=now;t.status='PAUSED';t.ceoDecision={decision:'REJECTED',at:now};if(e){e.status='READY';e.task=''}addActivity(s,'نواف رفض: '+t.title,'REAL');toast('تم رفض المهمة وإيقافها.');
 }
 write(s,'ceo-decision');cloudPush();window.NawafHQ3D?.routeEmployee?.(t.employeeId,rerun?'READY':'IDLE');render(true);if(rerun&&window.NawafAgents?.runTask)setTimeout(()=>window.NawafAgents.runTask(t.id),450)}
function ensureStyle(){if(document.getElementById('ceo-decision-style'))return;const x=document.createElement('style');x.id='ceo-decision-style';x.textContent=`
.ceo-decisions{margin:16px 0;border:1px solid rgba(239,190,90,.25);background:linear-gradient(180deg,rgba(26,20,13,.92),rgba(11,15,21,.96));border-radius:18px;padding:15px}.ceo-decisions h2{margin:0;font-size:16px}.ceo-decisions p{margin:5px 0 0;color:var(--muted);font-size:10px}.ceo-list{display:grid;gap:9px;margin-top:12px}.ceo-decision{border:1px solid rgba(255,255,255,.08);background:#0d141d;border-radius:13px;padding:11px}.ceo-decision-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.ceo-decision b{font-size:12px}.ceo-decision small{display:block;color:var(--muted);margin-top:4px}.ceo-summary{font-size:10px;color:#b9c3cb;line-height:1.75;margin:9px 0}.ceo-buttons{display:flex;gap:7px;flex-wrap:wrap}.ceo-buttons button{border:1px solid rgba(255,255,255,.12);background:#151d27;color:#edf2f6;border-radius:9px;padding:7px 10px;font:650 10px system-ui;cursor:pointer}.ceo-buttons .approve{background:linear-gradient(135deg,#e1b85f,#9f7330);color:#111;border-color:#d9ad55}.ceo-count{min-width:28px;height:28px;border-radius:999px;display:grid;place-items:center;background:#e0b65d;color:#111;font-weight:800}.nav [data-view="approvals"] .ceo-badge{margin-inline-start:auto;background:#dcae52;color:#111;border-radius:999px;min-width:18px;padding:1px 5px;font-size:8px;text-align:center}.ceo-empty{padding:12px;text-align:center;color:var(--muted);font-size:10px}`;document.head.appendChild(x)}
function markup(s){const list=(s.approvals||[]).filter(a=>a.status==='WAITING');return `<section class="ceo-decisions" id="ceo-decisions"><div class="ceo-decision-head"><div><h2>مركز قرارات نواف</h2><p>يعرض فقط المهام التي توقفت فعليًا بانتظار قرارك.</p></div><div class="ceo-count">${list.length}</div></div><div class="ceo-list">${list.length?list.map(a=>{const t=(s.tasks||[]).find(x=>x.id===a.taskId),e=employee(s,a.employeeId);const summary=a.summary||resultText(t);return `<div class="ceo-decision"><div class="ceo-decision-head"><div><b>${esc(a.title)}</b><small>${esc(e?.name||a.requester||'موظف AI')} • ${esc(projectName(s,a.projectId))}</small></div></div>${summary?`<div class="ceo-summary">${esc(summary.slice(0,260))}</div>`:''}<div class="ceo-buttons"><button class="approve" data-ceo="approve" data-id="${esc(a.id)}">اعتماد ومتابعة</button><button data-ceo="changes" data-id="${esc(a.id)}">طلب تعديل</button><button data-ceo="reject" data-id="${esc(a.id)}">رفض</button></div></div>`}).join(''):'<div class="ceo-empty">ما فيه شيء ينتظر قرارك الآن.</div>'}</div></section>`}
function badge(s){const n=(s.approvals||[]).filter(a=>a.status==='WAITING').length;document.querySelectorAll('[data-view="approvals"]').forEach(b=>{let x=b.querySelector('.ceo-badge');if(!x&&n){x=document.createElement('span');x.className='ceo-badge';b.appendChild(x)}if(x){x.textContent=n;x.style.display=n?'':'none'}})}
function bind(node){node.querySelectorAll('[data-ceo]').forEach(b=>b.addEventListener('click',()=>decide(b.dataset.id,b.dataset.ceo)))}
function render(force=false){ensureStyle();const s=normalize(),raw=JSON.stringify({a:s.approvals,t:(s.tasks||[]).map(t=>[t.id,t.status,t.progress])});if(!force&&raw===last){badge(s);return}last=raw;badge(s);const title=document.getElementById('page-title')?.textContent||'';if(!['لوحة القيادة','موافقات CEO','المقر التفاعلي'].includes(title))return;const content=document.getElementById('content');if(!content)return;let node=document.getElementById('ceo-decisions');const wrap=document.createElement('div');wrap.innerHTML=markup(s);const fresh=wrap.firstElementChild;if(node)node.replaceWith(fresh);else content.prepend(fresh);bind(fresh)}
['nawaf:state-updated','nawaf:activity-updated','hq:office-ready'].forEach(name=>window.addEventListener(name,()=>setTimeout(()=>render(true),80)));window.addEventListener('storage',e=>{if(e.key===KEY)render(true)});new MutationObserver(()=>render(false)).observe(document.documentElement,{childList:true,subtree:true});setInterval(()=>render(false),1000);document.readyState==='loading'?document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>render(true),1200)):setTimeout(()=>render(true),1200);window.NawafCEO={render:()=>render(true),decide};
})();
